    19	struct Cli {
    20	    /// Use this exact 8-digit bootstrap PIN.
    21	    #[arg(long, value_name = "PIN", conflicts_with = "pin")]
    22	    bootstrap_pin: Option<String>,
    23	
    24	    /// Generate and display a fresh 8-digit bootstrap PIN (`--pin generate`).
    25	    #[arg(long, value_name = "generate", conflicts_with = "bootstrap_pin")]
    26	    pin: Option<String>,
    27	
    28	    /// List persisted paired devices and exit.
    29	    #[arg(long, conflicts_with_all = ["revoke", "bootstrap_pin", "pin"])]
    30	    list_paired: bool,
    31	
    32	    /// Revoke one pairing ID and exit.
    33	    #[arg(long, value_name = "ID", conflicts_with_all = ["list_paired", "bootstrap_pin", "pin"])]
    34	    revoke: Option<String>,
    35	
    36	    /// LAN HEVC bitrate in Mbps. Accepted range: 50 through 150.
    37	    /// Without this flag the compatibility default is 8 Mbps.
    38	    #[arg(long, value_name = "MBPS", value_parser = clap::value_parser!(u32).range(50..=150))]
    39	    lan_bitrate_mbps: Option<u32>,
