    46	fn main() -> Result<()> {
    47	    tracing_subscriber::fmt()
    48	        .with_env_filter(
    49	            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
    50	        )
    51	        .init();
    52	
    53	    let cli = Cli::parse();
    54	    let store = PairingStore::host_default()?;
    55	    if cli.list_paired {
    56	        let mut records = store.load_all()?;
    57	        records.sort_by(|left, right| right.added_at_unix_ms.cmp(&left.added_at_unix_ms));
    58	        if records.is_empty() {
    59	            println!("No paired devices.");
    60	        } else {
    61	            for record in records {
    62	                println!(
    63	                    "{}\t{}\t{}",
    64	                    record.id, record.name, record.added_at_unix_ms
    65	                );
    66	            }
    67	        }
    68	        return Ok(());
    69	    }
    70	    if let Some(id) = cli.revoke {
    71	        if store.revoke(&id)? {
    72	            println!("Revoked pairing {id}");
    73	        } else {
    74	            bail!("pairing ID not found: {id}");
    75	        }
    76	        return Ok(());
    77	    }
    78	
    79	    let pin = match (cli.bootstrap_pin, cli.pin.as_deref()) {
    80	        (Some(pin), None) => validate_pin(pin)?,
    81	        (None, Some("generate")) | (None, None) => random_pin(),
    82	        (None, Some(other)) => bail!("--pin accepts only 'generate', got '{other}'"),
    83	        (Some(_), Some(_)) => unreachable!("clap enforces conflicts"),
    84	    };
