   109	
   110	fn validate_pin(pin: String) -> Result<String> {
   111	    if pin.len() != 8 || !pin.bytes().all(|byte| byte.is_ascii_digit()) {
   112	        bail!("bootstrap PIN must be exactly 8 decimal digits");
   113	    }
   114	    Ok(pin)
   115	}
   116	
   117	fn consent_loop(receiver: mpsc::Receiver<ConsentPrompt>) {
   118	    let stdin = io::stdin();
   119	    let mut lines = stdin.lock().lines();
   120	    while let Ok(prompt) = receiver.recv() {
   121	        print!("Approve pairing for '{}' [y/N]? ", prompt.client_name);
   122	        let _ = io::stdout().flush();
   123	        let approved = lines
   124	            .next()
   125	            .and_then(Result::ok)
   126	            .is_some_and(|line| matches!(line.trim().to_ascii_lowercase().as_str(), "y" | "yes"));
   127	        prompt.respond(approved);
   128	    }
   129	}
