   134	        fn CGPreflightScreenCaptureAccess() -> bool;
   135	        fn CGRequestScreenCaptureAccess() -> bool;
   136	    }
   137	
   138	    let screen_recording = unsafe { CGPreflightScreenCaptureAccess() };
   139	    if !screen_recording {
   140	        eprintln!(
   141	            "Screen Recording permission is required. macOS will prompt now; grant it in System Settings > Privacy & Security > Screen Recording, then relaunch erd-host."
   142	        );
   143	        let _ = unsafe { CGRequestScreenCaptureAccess() };
   144	    }
   145	    if !accessibility_is_trusted() {
   146	        eprintln!(
   147	            "Accessibility permission is required for remote input. macOS will prompt now; enable erd-host (or this terminal) in System Settings > Privacy & Security > Accessibility, then relaunch."
   148	        );
   149	        let _ = request_accessibility();
   150	    }
   151	}
