 244	impl SessionState {
 245	    pub fn allows(self, packet_type: PacketType) -> bool {
 246	        match self {
 247	            Self::PreAuth => matches!(
 248	                packet_type,
 249	                PacketType::PairingRequest | PacketType::Handshake
 250	            ),
 251	            Self::PairingGranted => matches!(packet_type, PacketType::Handshake),
 252	            Self::Authenticated => matches!(
 253	                packet_type,
