 261	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 262	pub struct TimestampStats {
 263	    pub frame_id: u32,
 264	    pub capture_us: u64,
 265	    pub encode_start_us: u64,
 266	    pub encode_end_us: u64,
 267	    pub send_us: u64,
 268	}
 269	
 270	impl TimestampStats {
 271	    pub const SIZE: usize = 6 + 4 + 8 * 4;
 272	
 273	    pub fn encode(self) -> Vec<u8> {
 274	        let mut output = Vec::with_capacity(Self::SIZE);
 275	        output.extend_from_slice(TIMESTAMP_STATS_MAGIC);
 276	        output.extend_from_slice(&self.frame_id.to_le_bytes());
 277	        output.extend_from_slice(&self.capture_us.to_le_bytes());
 278	        output.extend_from_slice(&self.encode_start_us.to_le_bytes());
 279	        output.extend_from_slice(&self.encode_end_us.to_le_bytes());
 280	        output.extend_from_slice(&self.send_us.to_le_bytes());
 281	        output
 282	    }
 283	
 284	    pub fn decode(bytes: &[u8]) -> Option<Self> {
 285	        if bytes.len() != Self::SIZE || &bytes[..6] != TIMESTAMP_STATS_MAGIC {
 286	            return None;
 287	        }
 288	        Some(Self {
 289	            frame_id: u32::from_le_bytes(bytes[6..10].try_into().ok()?),
 290	            capture_us: u64::from_le_bytes(bytes[10..18].try_into().ok()?),
 291	            encode_start_us: u64::from_le_bytes(bytes[18..26].try_into().ok()?),
 292	            encode_end_us: u64::from_le_bytes(bytes[26..34].try_into().ok()?),
 293	            send_us: u64::from_le_bytes(bytes[34..42].try_into().ok()?),
 294	        })
 295	    }
 296	}
