 363	impl MediaSource for MacMediaSource {
 364	    fn start(&self, sender: SyncSender<MediaEvent>) -> Result<Box<dyn MediaHandle>, SessionError> {
 365	        let (capture, capture_rx) = ScreenCapture::start(self.config)?;
 366	        let (encoder, encoded_rx) = VideoToolboxEncoder::start(self.encoder)?;
 367	        let command_sender = encoder.sender.clone();
 368	        let capture_sender = sender.clone();
 369	        let capture_bridge = thread::Builder::new()
 370	            .name("erd-host-capture-bridge".into())
 371	            .spawn(move || {
 372	                while let Ok(event) = capture_rx.recv() {
 373	                    match event {
 374	                        CaptureEvent::Video(frame) => {
 375	                            if command_sender
 376	                                .send(crate::encode_vt::Command::Frame(frame))
 377	                                .is_err()
 378	                            {
 379	                                break;
 380	                            }
 381	                        }
 382	                        CaptureEvent::Audio {
 383	                            pcm_f32_le,
 384	                            captured_at,
 385	                        } => {
 386	                            if capture_sender
 387	                                .send(MediaEvent::Audio(pcm_f32_le, captured_at))
 388	                                .is_err()
 389	                            {
 390	                                break;
 391	                            }
 392	                        }
 393	                        CaptureEvent::Stopped(error) => {
 394	                            let _ = capture_sender.send(MediaEvent::Error(error));
 395	                            break;
 396	                        }
 397	                    }
 398	                }
 399	            })?;
 400	        let encoded_bridge = thread::Builder::new()
 401	            .name("erd-host-encoded-bridge".into())
 402	            .spawn(move || {
 403	                while let Ok(result) = encoded_rx.recv() {
 404	                    let event = match result {
 405	                        Ok(frame) => MediaEvent::Video(frame),
 406	                        Err(error) => MediaEvent::Error(error.to_string()),
 407	                    };
 408	                    if sender.send(event).is_err() {
 409	                        break;
 410	                    }
 411	                }
 412	            })?;
 413	        Ok(Box::new(MacMediaHandle {
 414	            capture: Some(capture),
 415	            encoder: Some(encoder),
 416	            capture_bridge: Some(capture_bridge),
 417	            encoded_bridge: Some(encoded_bridge),
 418	        }))
 419	    }
 420	}
