 441	            let _ = capture.stop();
 442	        }
 443	        if let Some(encoder) = self.encoder.take() {
 444	            encoder.stop();
 445	        }
 446	        if let Some(bridge) = self.capture_bridge.take() {
 447	            let _ = bridge.join();
 448	        }
 449	        if let Some(bridge) = self.encoded_bridge.take() {
 450	            let _ = bridge.join();
 451	        }
 452	    }
