 555	
 556	    fn bind_with_media(
 557	        config: HostConfig,
 558	        media_source: Arc<dyn MediaSource>,
 559	    ) -> Result<Self, SessionError> {
 560	        if config
 561	            .bootstrap_pin
 562	            .as_ref()
 563	            .is_some_and(|pin| pin.len() != 8 || !pin.bytes().all(|byte| byte.is_ascii_digit()))
 564	        {
 565	            return Err(SessionError::InvalidPin);
 566	        }
 567	        let tcp_listener = TcpListener::bind(config.tcp_addr)?;
 568	        let udp_socket = UdpSocket::bind(config.udp_addr)?;
 569	        udp_socket.set_nonblocking(true)?;
 570	        let lockout = Arc::new(Mutex::new(BootstrapLockout::default()));
 571	        let pairing_deadline = config
 572	            .bootstrap_pin
 573	            .as_ref()
 574	            .map(|_| Instant::now() + config.pairing_window);
 575	        if pairing_deadline.is_some() {
 576	            lockout.lock().expect("lockout poisoned").begin_pairing();
 577	        }
 578	        Ok(Self {
 579	            config,
 580	            tcp_listener,
 581	            udp_socket,
 582	            media_source,
 583	            lockout,
 584	            pairing_deadline,
 585	        })
 586	    }
 587	
 588	    pub fn tcp_addr(&self) -> Result<SocketAddr, SessionError> {
 589	        Ok(self.tcp_listener.local_addr()?)
 590	    }
 591	
 592	    pub fn udp_addr(&self) -> Result<SocketAddr, SessionError> {
 593	        Ok(self.udp_socket.local_addr()?)
 594	    }
 595	
 596	    pub fn serve(self) -> Result<(), SessionError> {
 597	        loop {
 598	            if let Err(error) = self.serve_next() {
 599	                warn!(%error, "connection ended with an error");
 600	            }
 601	        }
 602	    }
 603	
 604	    pub fn serve_n(&self, connection_count: usize) -> Result<(), SessionError> {
 605	        for _ in 0..connection_count {
 606	            self.serve_next()?;
 607	        }
 608	        Ok(())
 609	    }
 610	
 611	    fn serve_next(&self) -> Result<(), SessionError> {
 612	        let (tcp, peer) = self.tcp_listener.accept()?;
 613	        tcp.set_nodelay(true)?;
 614	        let tls_server = TlsPskServer::new(self.current_psks()?)?;
 615	        match tls_server.accept_stream(tcp) {
 616	            Ok(stream) => self.handle_connection(stream, peer),
 617	            Err(error) => {
 618	                let locked = self
 619	                    .lockout
 620	                    .lock()
 621	                    .expect("lockout poisoned")
 622	                    .record_failure(Instant::now());
 623	                if locked {
 624	                    warn!("bootstrap TLS path locked after repeated failures");
 625	                }
 626	                Err(SessionError::Tls(error))
 627	            }
 628	        }
 629	    }
 630	
 631	    fn current_psks(&self) -> Result<Vec<PskIdentity>, SessionError> {
 632	        let mut psks = self
 633	            .config
 634	            .pairing_store
 635	            .load_all()?
 636	            .into_iter()
 637	            .map(|record| PskIdentity::pairing(&record.id, &record.key))
 638	            .collect::<Result<Vec<_>, _>>()?;
 639	        let pairing_active = self
 640	            .pairing_deadline
 641	            .is_some_and(|deadline| Instant::now() < deadline)
 642	            && self
 643	                .lockout
 644	                .lock()
 645	                .expect("lockout poisoned")
 646	                .is_allowed(Instant::now());
 647	        if pairing_active {
 648	            if let Some(pin) = &self.config.bootstrap_pin {
 649	                psks.push(PskIdentity::bootstrap(pin)?);
 650	            }
 651	        }
 652	        if psks.is_empty() {
 653	            let mut disabled_key = [0_u8; 32];
 654	            rand::rng().fill_bytes(&mut disabled_key);
 655	            psks.push(PskIdentity::new("erd-disabled", disabled_key.to_vec())?);
 656	        }
 657	        Ok(psks)
 658	    }
 659	
 660	    fn is_pairing_active(&self) -> bool {
 661	        self.pairing_deadline
 662	            .is_some_and(|deadline| Instant::now() < deadline)
 663	            && self
 664	                .lockout
 665	                .lock()
 666	                .expect("lockout poisoned")
 667	                .is_allowed(Instant::now())
 668	    }
 669	
 670	    fn handle_connection(
 671	        &self,
 672	        mut stream: erd_net::TlsPskStream<TcpStream>,
 673	        tcp_peer: SocketAddr,
 674	    ) -> Result<(), SessionError> {
 675	        stream
 676	            .ssl_stream_mut()
 677	            .get_mut()
 678	            .set_read_timeout(Some(Duration::from_millis(100)))?;
 679	        let negotiated_identity = stream
 680	            .negotiated_identity()
 681	            .and_then(|identity| std::str::from_utf8(identity).ok())
 682	            .unwrap_or_default()
 683	            .to_owned();
 684	        let mut state = SessionState::PreAuth;
 685	        let mut c2h_cipher = None;
 686	        let mut h2c_cipher = None;
 687	        let mut udp_peer = None;
 688	        let mut media_receiver: Option<Receiver<MediaEvent>> = None;
 689	        let mut media_handle: Option<Box<dyn MediaHandle>> = None;
 690	        let input = InputInjector::new(
 691	            self.config.display.logical_width as f32,
 692	            self.config.display.logical_height as f32,
 693	        );
 694	        let session_origin = Instant::now();
 695	        let mut last_pong = Instant::now();
 696	        let mut next_ping = Instant::now() + HEARTBEAT_INTERVAL;
 697	        let mut udp_sender = UdpSender::default();
 698	
 699	        info!(identity = negotiated_identity, peer = %tcp_peer, "TLS-PSK session established");
 700	        loop {
 701	            self.discover_udp_peer(tcp_peer, &mut udp_peer, c2h_cipher.as_mut())?;
 702	            if state == SessionState::Authenticated {
 703	                if let (Some(receiver), Some(peer)) = (&media_receiver, udp_peer) {
 704	                    while let Ok(event) = receiver.try_recv() {
 705	                        match event {
 706	                            MediaEvent::Video(frame) => udp_sender.send_frame(
 707	                                &self.udp_socket,
 708	                                peer,
 709	                                h2c_cipher.as_mut().ok_or(SessionError::PreAuth)?,
 710	                                self.config.display.pixel_width,
 711	                                self.config.display.pixel_height,
 712	                                frame,
 713	                                session_origin,
 714	                            )?,
 715	                            MediaEvent::Audio(bytes, _captured_at) => udp_sender.send_audio(
 716	                                &self.udp_socket,
 717	                                peer,
 718	                                h2c_cipher.as_mut().ok_or(SessionError::PreAuth)?,
 719	                                &bytes,
 720	                            )?,
 721	                            MediaEvent::Error(error) => return Err(SessionError::Store(error)),
 722	                        }
 723	                    }
 724	                }
 725	                let now = Instant::now();
 726	                if now >= next_ping {
 727	                    send_tcp_control(&mut stream, ControlMessage::Ping)?;
 728	                    next_ping = now + HEARTBEAT_INTERVAL;
 729	                }
 730	                if now.duration_since(last_pong) >= HEARTBEAT_TIMEOUT {
 731	                    warn!(peer = %tcp_peer, "heartbeat timeout");
 732	                    break;
 733	                }
 734	            }
 735	
 736	            let packet = match stream.read_frame() {
 737	                Ok(packet) => packet,
 738	                Err(TlsPskError::Io(error))
 739	                    if matches!(
 740	                        error.kind(),
 741	                        io::ErrorKind::WouldBlock | io::ErrorKind::TimedOut
 742	                    ) =>
 743	                {
 744	                    continue
 745	                }
 746	                Err(TlsPskError::Io(error))
 747	                    if matches!(
 748	                        error.kind(),
 749	                        io::ErrorKind::UnexpectedEof
 750	                            | io::ErrorKind::ConnectionReset
 751	                            | io::ErrorKind::BrokenPipe
 752	                    ) =>
 753	                {
 754	                    break
 755	                }
 756	                Err(error) => return Err(SessionError::Tls(error)),
 757	            };
 758	            let (header, payload) = split_packet(&packet)?;
 759	            if !state.allows(header.packet_type) {
 760	                debug!(?state, ?header.packet_type, "refusing pre-auth packet");
 761	                continue;
 762	            }
 763	
 764	            match header.packet_type {
 765	                PacketType::PairingRequest => {
 766	                    if negotiated_identity != BOOTSTRAP_IDENTITY || !self.is_pairing_active() {
 767	                        send_pairing_reject(&mut stream, PairingRejectReason::PairingDisabled)?;
 768	                        continue;
 769	                    }
 770	                    let request = PairingRequest::decode(payload)?;
 771	                    let Some(consent_sender) = &self.config.consent_sender else {
 772	                        send_pairing_reject(&mut stream, PairingRejectReason::PairingDisabled)?;
 773	                        continue;
 774	                    };
 775	                    let (response_tx, response_rx) = mpsc::sync_channel(1);
 776	                    consent_sender
 777	                        .send(ConsentPrompt {
 778	                            client_name: request.name.clone(),
 779	                            response: response_tx,
 780	                        })
 781	                        .map_err(|_| SessionError::ConsentUnavailable)?;
 782	                    let approved = response_rx
 783	                        .recv_timeout(self.config.pairing_window)
 784	                        .map_err(|_| SessionError::ConsentTimeout)?;
 785	                    if !approved {
 786	                        send_pairing_reject(&mut stream, PairingRejectReason::DeniedByHost)?;
 787	                        break;
 788	                    }
 789	                    let record = PairingRecord {
 790	                        id: Uuid::new_v4().to_string().to_uppercase(),
 791	                        name: request.name,
 792	                        key: random_key(),
 793	                        added_at_unix_ms: unix_ms_u64(),
 794	                    };
 795	                    self.config.pairing_store.save(record.clone())?;
 796	                    let grant = PairingGrant {
 797	                        pairing_id: record.id,
 798	                        host_name: self.config.host_name.clone(),
 799	                        key: record.key,
 800	                    };
 801	                    send_tcp_packet(&mut stream, PacketType::PairingGrant, &grant.encode()?)?;
 802	                    state = SessionState::PairingGranted;
 803	                }
 804	                PacketType::Handshake => {
 805	                    let handshake = Handshake::decode(payload)?;
 806	                    let record = self
 807	                        .config
 808	                        .pairing_store
 809	                        .load(&handshake.pairing_id)?
 810	                        .ok_or(SessionError::UnknownPairing)?;
 811	                    if let Some(identity_pairing_id) =
 812	                        negotiated_identity.strip_prefix(PAIRING_IDENTITY_PREFIX)
 813	                    {
 814	                        if identity_pairing_id != handshake.pairing_id {
 815	                            return Err(SessionError::IdentityMismatch);
 816	                        }
 817	                    } else if negotiated_identity != BOOTSTRAP_IDENTITY {
 818	                        return Err(SessionError::IdentityMismatch);
 819	                    }
 820	                    if handshake.version != PROTOCOL_VERSION {
 821	                        return Err(SessionError::Codec(
 822	                            erd_proto::CodecError::UnsupportedVersion(handshake.version),
 823	                        ));
 824	                    }
 825	                    c2h_cipher = Some(DatagramCipher::derive(
 826	                        &record.key,
 827	                        &handshake.session_salt,
 828	                        Direction::ClientToHost,
 829	                    )?);
 830	                    h2c_cipher = Some(DatagramCipher::derive(
 831	                        &record.key,
 832	                        &handshake.session_salt,
 833	                        Direction::HostToClient,
 834	                    )?);
 835	                    state = SessionState::Authenticated;
 836	                    let ack = Handshake {
 837	                        name: self.config.host_name.clone(),
 838	                        width: self.config.display.logical_width.min(u16::MAX as u32) as u16,
 839	                        height: self.config.display.logical_height.min(u16::MAX as u32) as u16,
 840	                        scale: self.config.display.scale_factor(),
 841	                        version: PROTOCOL_VERSION,
 842	                        capabilities: Capabilities::STREAM_CONFIGURATION,
 843	                        pairing_id: String::new(),
 844	                        session_salt: [0_u8; 16],
 845	                    };
 846	                    send_tcp_packet(&mut stream, PacketType::HandshakeAck, &ack.encode()?)?;
 847	                    let (media_tx, media_rx) = mpsc::sync_channel(3);
 848	                    media_handle = Some(self.media_source.start(media_tx)?);
 849	                    media_receiver = Some(media_rx);
 850	                    last_pong = Instant::now();
 851	                    next_ping = Instant::now() + HEARTBEAT_INTERVAL;
 852	                    info!(
 853	                        client = handshake.name,
 854	                        "v3 handshake authenticated; UDP ciphers armed"
 855	                    );
 856	                }
 857	                PacketType::InputEvent => {
 858	                    if state != SessionState::Authenticated {
 859	                        continue;
 860	                    }
 861	                    let event = InputEvent::decode(payload)?;
 862	                    if let Err(error) = input.inject(&event) {
 863	                        debug!(%error, "input event was not injected");
 864	                    }
 865	                }
 866	                PacketType::Control => {
 867	                    if state != SessionState::Authenticated {
 868	                        continue;
 869	                    }
 870	                    match ControlMessage::decode(payload)? {
 871	                        ControlMessage::RequestKeyFrame => {
 872	                            if let Some(media) = &media_handle {
 873	                                media.force_key_frame()?;
 874	                            }
 875	                        }
 876	                        ControlMessage::BitrateAdjust(BitrateAdjust { target_bitrate })
 877	                            if target_bitrate > 0 =>
 878	                        {
 879	                            if let Some(media) = &media_handle {
 880	                                media.update_bitrate(target_bitrate as u32)?;
 881	                            }
 882	                        }
 883	                        ControlMessage::Ping => {
 884	                            send_tcp_control(&mut stream, ControlMessage::Pong)?;
 885	                        }
 886	                        ControlMessage::Pong => last_pong = Instant::now(),
 887	                        ControlMessage::Disconnect | ControlMessage::StopStream => break,
 888	                        _ => {}
 889	                    }
 890	                }
 891	                _ => {}
 892	            }
 893	        }
 894	
 895	        if let Some(mut media) = media_handle {
 896	            media.stop();
 897	        }
 898	        state = SessionState::Closed;
 899	        debug!(?state, "session closed");
 900	        Ok(())
 901	    }
