 903	    fn discover_udp_peer(
 904	        &self,
 905	        tcp_peer: SocketAddr,
 906	        udp_peer: &mut Option<SocketAddr>,
 907	        receive_cipher: Option<&mut DatagramCipher>,
 908	    ) -> Result<(), SessionError> {
 909	        let mut buffer = [0_u8; 2_048];
 910	        loop {
 911	            match self.udp_socket.recv_from(&mut buffer) {
 912	                Ok((length, peer)) if peer.ip() == tcp_peer.ip() => {
 913	                    if length == 1 && buffer[0] == 0xff {
 914	                        *udp_peer = Some(peer);
 915	                    } else if let Some(cipher) = receive_cipher {
 916	                        let _ = cipher.open_datagram(&buffer[..length]);
 917	                        *udp_peer = Some(peer);
 918	                    }
 919	                    return Ok(());
 920	                }
 921	                Ok(_) => continue,
 922	                Err(error) if error.kind() == io::ErrorKind::WouldBlock => return Ok(()),
 923	                Err(error) => return Err(SessionError::Io(error)),
 924	            }
 925	        }
 926	    }
 927	}
