 936	impl UdpSender {
 937	    fn send_packet(
 938	        &mut self,
 939	        socket: &UdpSocket,
 940	        peer: SocketAddr,
 941	        cipher: &mut DatagramCipher,
 942	        packet_type: PacketType,
 943	        payload: &[u8],
 944	    ) -> Result<(), SessionError> {
 945	        self.sequence = self.sequence.wrapping_add(1);
 946	        let header = PacketHeader::new(packet_type, self.sequence, unix_ms_u32(), 0);
 947	        let datagram = cipher.seal_datagram(&header, payload)?;
 948	        socket.send_to(&datagram, peer)?;
 949	        Ok(())
 950	    }
 951	
 952	    fn send_frame(
 953	        &mut self,
 954	        socket: &UdpSocket,
 955	        peer: SocketAddr,
 956	        cipher: &mut DatagramCipher,
 957	        width: u32,
 958	        height: u32,
 959	        frame: EncodedFrame,
 960	        session_origin: Instant,
 961	    ) -> Result<(), SessionError> {
 962	        self.frame_id = self.frame_id.wrapping_add(1);
 963	        let frame_id = self.frame_id;
 964	        let chunk_count = frame.data.len().div_ceil(MAX_VIDEO_CHUNK_BYTES);
 965	        let header = FrameHeader {
 966	            frame_id,
 967	            width: width.min(u16::MAX as u32) as u16,
 968	            height: height.min(u16::MAX as u32) as u16,
 969	            is_key_frame: frame.is_key_frame,
 970	            total_chunks: u16::try_from(chunk_count)
 971	                .map_err(|_| SessionError::Store("encoded frame has too many chunks".into()))?,
 972	            total_size: u32::try_from(frame.data.len())
 973	                .map_err(|_| SessionError::Store("encoded frame is too large".into()))?,
 974	        };
 975	        self.send_packet(
 976	            socket,
 977	            peer,
 978	            cipher,
 979	            PacketType::FrameHeader,
 980	            &header.encode()?,
 981	        )?;
 982	        for (index, bytes) in frame.data.chunks(MAX_VIDEO_CHUNK_BYTES).enumerate() {
 983	            let chunk = FrameChunk {
 984	                frame_id,
 985	                chunk_index: index as u16,
 986	                data: bytes.to_vec(),
 987	            };
 988	            self.send_packet(
 989	                socket,
 990	                peer,
 991	                cipher,
 992	                PacketType::FrameChunk,
 993	                &chunk.encode()?,
 994	            )?;
 995	        }
 996	        let send_at = Instant::now();
 997	        let stats = TimestampStats {
 998	            frame_id,
 999	            capture_us: monotonic_us(session_origin, frame.capture_at),
1000	            encode_start_us: monotonic_us(session_origin, frame.encode_started_at),
1001	            encode_end_us: monotonic_us(session_origin, frame.encode_completed_at),
1002	            send_us: monotonic_us(session_origin, send_at),
1003	        };
1004	        self.send_packet(socket, peer, cipher, PacketType::Ping, &stats.encode())?;
1005	        Ok(())
1006	    }
1007	
1008	    fn send_audio(
1009	        &mut self,
1010	        socket: &UdpSocket,
1011	        peer: SocketAddr,
1012	        cipher: &mut DatagramCipher,
1013	        bytes: &[u8],
1014	    ) -> Result<(), SessionError> {
1015	        if bytes.is_empty() {
1016	            return Ok(());
1017	        }
1018	        self.audio_frame_id = self.audio_frame_id.wrapping_add(1);
1019	        let fragment_count = bytes.len().div_ceil(MAX_AUDIO_FRAGMENT_BYTES);
1020	        let fragment_count = u16::try_from(fragment_count)
1021	            .map_err(|_| SessionError::Store("audio frame has too many fragments".into()))?;
1022	        for (index, data) in bytes.chunks(MAX_AUDIO_FRAGMENT_BYTES).enumerate() {
1023	            let fragment = AudioFragment {
1024	                header: AudioFragmentHeader {
1025	                    frame_id: self.audio_frame_id,
1026	                    fragment_index: index as u16,
1027	                    fragment_count,
1028	                },
1029	                data: data.to_vec(),
1030	            };
1031	            self.send_packet(
1032	                socket,
1033	                peer,
1034	                cipher,
1035	                PacketType::AudioFrame,
1036	                &fragment.encode()?,
1037	            )?;
1038	        }
1039	        Ok(())
1040	    }
1041	}
