1043	fn split_packet(packet: &[u8]) -> Result<(PacketHeader, &[u8]), SessionError> {
1044	    if packet.len() < PacketHeader::SIZE {
1045	        return Err(SessionError::Codec(erd_proto::CodecError::Truncated {
1046	            field: "packet header",
1047	            needed: PacketHeader::SIZE,
1048	            remaining: packet.len(),
1049	        }));
1050	    }
1051	    let header = PacketHeader::decode(&packet[..PacketHeader::SIZE])?;
1052	    Ok((header, &packet[PacketHeader::SIZE..]))
1053	}
