   164	impl ClientSession {
   165	    pub fn new(config: SessionConfig) -> Result<Self, SessionError> {
   166	        let store = match config.pairing_store_path.clone() {
   167	            Some(path) => PairingStore::new(path),
   168	            None => PairingStore::open_default()?,
   169	        };
   170	        Ok(Self {
