   181	    pub fn pair_with_pin(&self, pin: &str) -> Result<ReadySession, SessionError> {
   182	        let psk = PskIdentity::bootstrap(pin)?;
   183	        self.connect_with_psk(psk, SessionState::AwaitingPairing)?;
   184	        self.send_packet(
   185	            PacketType::PairingRequest,
   186	            &PairingRequest {
   187	                name: self.config.client_name.clone(),
   188	            }
   189	            .encode()?,
   190	        )?;
   191	        let (header, payload) = self.read_tcp_packet()?;
   192	        let pairing = match header.packet_type {
   193	            PacketType::PairingGrant => {
   194	                let grant = PairingGrant::decode(&payload)?;
   195	                let record = PairingRecord {
   196	                    id: grant.pairing_id,
   197	                    name: grant.host_name,
   198	                    key: grant.key.to_vec(),
   199	                    added_at_unix_ms: current_unix_ms() as u64,
   200	                };
   201	                self.store.save(record.clone())?;
   202	                record
   203	            }
   204	            PacketType::PairingReject => {
   205	                return Err(SessionError::PairingRejected(
   206	                    PairingReject::decode(&payload)?.reason,
   207	                ));
   208	            }
   209	            actual => {
   210	                return Err(SessionError::UnexpectedPacket {
   211	                    expected: PacketType::PairingGrant,
   212	                    actual,
   213	                });
   214	            }
   215	        };
   216	        self.begin_handshake(pairing)
   217	    }
