   219	    pub fn reconnect(&self, pairing_id: &str) -> Result<ReadySession, SessionError> {
   220	        let pairing = self
   221	            .store
   222	            .load(pairing_id)?
   223	            .ok_or_else(|| SessionError::PairingNotFound(pairing_id.to_owned()))?;
   224	        let psk = PskIdentity::pairing(&pairing.id, &pairing.key)?;
   225	        self.connect_with_psk(psk, SessionState::AwaitingHandshakeAck)?;
   226	        self.begin_handshake(pairing)
   227	    }
