   237	    pub fn send_udp(&self, packet_type: PacketType, payload: &[u8]) -> Result<(), SessionError> {
   238	        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   239	        if inner.state != SessionState::Ready {
   240	            return Err(SessionError::NotReady);
   241	        }
   242	        inner.next_udp_sequence = inner.next_udp_sequence.wrapping_add(1);
   243	        let header = PacketHeader::new(packet_type, inner.next_udp_sequence, current_unix_ms(), 0);
   244	        let datagram = inner
   245	            .udp_send
   246	            .as_mut()
   247	            .ok_or(SessionError::NotReady)?
   248	            .seal_datagram(&header, payload)?;
   249	        inner
   250	            .udp
   251	            .as_ref()
   252	            .ok_or(SessionError::NotReady)?
   253	            .send(&datagram)?;
   254	        Ok(())
   255	    }
