   305	    /// Starts a background TCP control loop and exposes decoded session events.
   306	    pub fn spawn_tcp_runtime(&self) -> Result<SessionRuntime, SessionError> {
   307	        if self.state()? != SessionState::Ready {
   308	            return Err(SessionError::NotReady);
   309	        }
   310	        {
   311	            let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   312	            inner
   313	                .tcp
   314	                .as_mut()
   315	                .ok_or(SessionError::NotReady)?
   316	                .ssl_stream_mut()
   317	                .get_ref()
   318	                .set_read_timeout(Some(TCP_RUNTIME_READ_SLICE))?;
   319	        }
   320	        let session = self.clone();
   321	        let (stop_tx, stop_rx) = mpsc::channel();
   322	        let (event_tx, event_rx) = mpsc::channel();
   323	        let worker = thread::spawn(move || loop {
   324	            if stop_rx.try_recv().is_ok() {
   325	                break;
   326	            }
   327	            match session.receive_tcp_event() {
   328	                Ok(SessionEvent::Ignored) => {}
   329	                Ok(event) => {
   330	                    if event_tx.send(Ok(event)).is_err() {
   331	                        break;
   332	                    }
   333	                }
   334	                Err(SessionError::Tls(TlsPskError::Io(error)))
   335	                    if matches!(
   336	                        error.kind(),
   337	                        io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock
   338	                    ) => {}
   339	                Err(error) => {
   340	                    let _ = event_tx.send(Err(error));
   341	                    break;
   342	                }
   343	            }
   344	        });
   345	        Ok(SessionRuntime {
   346	            events: event_rx,
   347	            stop: Some(stop_tx),
   348	            worker: Some(worker),
   349	        })
   350	    }
