   352	    pub fn receive_udp_event(&self) -> Result<SessionEvent, SessionError> {
   353	        let mut datagram = [0_u8; 65_536];
   354	        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   355	        if inner.state != SessionState::Ready {
   356	            return Err(SessionError::NotReady);
   357	        }
   358	        let received = inner
   359	            .udp
   360	            .as_ref()
   361	            .ok_or(SessionError::NotReady)?
   362	            .recv(&mut datagram)?;
   363	        let (header, payload) = inner
   364	            .udp_receive
   365	            .as_mut()
   366	            .ok_or(SessionError::NotReady)?
   367	            .open_datagram(&datagram[..received])?;
   368	        drop(inner);
   369	        self.handle_packet(header, payload, true)
   370	    }
