   384	    fn connect_with_psk(
   385	        &self,
   386	        psk: PskIdentity,
   387	        next_state: SessionState,
   388	    ) -> Result<(), SessionError> {
   389	        {
   390	            let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   391	            inner.state = SessionState::Connecting;
   392	        }
   393	        let address = resolve_one((&*self.config.host, self.config.tcp_port))?;
   394	        let tcp = std::net::TcpStream::connect_timeout(&address, self.config.connect_timeout)?;
   395	        tcp.set_read_timeout(Some(self.config.connect_timeout))?;
   396	        tcp.set_write_timeout(Some(self.config.connect_timeout))?;
   397	        tcp.set_nodelay(true)?;
   398	        let stream = TlsPskClient::new(psk)?.connect_stream(tcp)?;
   399	        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   400	        inner.tcp = Some(stream);
   401	        inner.state = next_state;
   402	        Ok(())
   403	    }
