   405	    fn begin_handshake(&self, pairing: PairingRecord) -> Result<ReadySession, SessionError> {
   406	        let mut salt = [0_u8; 16];
   407	        OsRng.fill_bytes(&mut salt);
   408	        let handshake = Handshake {
   409	            name: self.config.client_name.clone(),
   410	            width: 0,
   411	            height: 0,
   412	            scale: 1.0,
   413	            version: PROTOCOL_VERSION,
   414	            capabilities: self.config.capabilities,
   415	            pairing_id: pairing.id.clone(),
   416	            session_salt: salt,
   417	        };
   418	        {
   419	            let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   420	            inner.pairing = Some(pairing.clone());
   421	            inner.session_salt = Some(salt);
   422	            inner.state = SessionState::AwaitingHandshakeAck;
   423	            if let Some(tcp) = inner.tcp.as_mut() {
   424	                tcp.ssl_stream_mut()
   425	                    .get_ref()
   426	                    .set_read_timeout(Some(self.config.handshake_ack_timeout))?;
   427	            }
   428	        }
   429	        self.send_packet(PacketType::Handshake, &handshake.encode()?)?;
   430	        let (header, payload) = match self.read_tcp_packet() {
   431	            Ok(packet) => packet,
   432	            Err(SessionError::Tls(TlsPskError::Io(error)))
   433	                if matches!(
   434	                    error.kind(),
   435	                    io::ErrorKind::TimedOut | io::ErrorKind::WouldBlock
   436	                ) =>
   437	            {
   438	                return Err(SessionError::HandshakeAckTimeout);
   439	            }
   440	            Err(error) => return Err(error),
   441	        };
   442	        if header.packet_type != PacketType::HandshakeAck {
   443	            return Err(SessionError::UnexpectedPacket {
   444	                expected: PacketType::HandshakeAck,
   445	                actual: header.packet_type,
   446	            });
   447	        }
   448	        let server = Handshake::decode(&payload)?;
   449	        let key = pairing.key_array()?;
   450	        let udp_send = DatagramCipher::derive(&key, &salt, Direction::ClientToHost)?;
   451	        let udp_receive = DatagramCipher::derive(&key, &salt, Direction::HostToClient)?;
   452	        let udp_address = resolve_one((&*self.config.host, self.config.udp_port))?;
   453	        let udp = UdpSocket::bind(if udp_address.is_ipv6() {
   454	            "[::]:0"
   455	        } else {
   456	            "0.0.0.0:0"
   457	        })?;
   458	        udp.connect(udp_address)?;
   459	        udp.set_read_timeout(Some(HEARTBEAT_INTERVAL * 3))?;
   460	        udp.send(&[0xff])?;
   461	        if let Some(tcp) = self
   462	            .inner
   463	            .lock()
   464	            .map_err(|_| SessionError::Poisoned)?
   465	            .tcp
   466	            .as_mut()
   467	        {
   468	            tcp.ssl_stream_mut().get_ref().set_read_timeout(None)?;
   469	        }
   470	        let ready = ReadySession {
   471	            pairing: pairing.clone(),
   472	            server: server.clone(),
   473	            session_salt: salt,
   474	        };
   475	        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   476	        inner.udp = Some(udp);
   477	        inner.udp_send = Some(udp_send);
   478	        inner.udp_receive = Some(udp_receive);
   479	        inner.server = Some(server);
   480	        inner.state = SessionState::Ready;
   481	        Ok(ready)
   482	    }
