   484	    fn send_ready_packet(
   485	        &self,
   486	        packet_type: PacketType,
   487	        payload: &[u8],
   488	    ) -> Result<(), SessionError> {
   489	        if self.state()? != SessionState::Ready {
   490	            return Err(SessionError::NotReady);
   491	        }
   492	        self.send_packet(packet_type, payload)
   493	    }
   494	
   495	    fn send_packet(&self, packet_type: PacketType, payload: &[u8]) -> Result<(), SessionError> {
   496	        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   497	        inner.next_tcp_sequence = inner.next_tcp_sequence.wrapping_add(1);
   498	        let header = PacketHeader::new(packet_type, inner.next_tcp_sequence, current_unix_ms(), 0);
   499	        let mut packet = header.encode()?;
   500	        packet.extend_from_slice(payload);
   501	        inner
   502	            .tcp
   503	            .as_mut()
   504	            .ok_or(SessionError::NotReady)?
   505	            .write_frame(&packet)?;
   506	        Ok(())
   507	    }
   508	
   509	    fn read_tcp_packet(&self) -> Result<(PacketHeader, Vec<u8>), SessionError> {
   510	        let frame = self
   511	            .inner
   512	            .lock()
   513	            .map_err(|_| SessionError::Poisoned)?
   514	            .tcp
   515	            .as_mut()
   516	            .ok_or(SessionError::NotReady)?
   517	            .read_frame()?;
   518	        if frame.len() < PacketHeader::SIZE {
   519	            return Err(SessionError::Io(io::Error::new(
   520	                io::ErrorKind::InvalidData,
   521	                "TCP packet is shorter than the v3 header",
   522	            )));
   523	        }
   524	        Ok((
   525	            PacketHeader::decode(&frame[..PacketHeader::SIZE])?,
   526	            frame[PacketHeader::SIZE..].to_vec(),
   527	        ))
   528	    }
   529	
   530	    fn handle_packet(
   531	        &self,
   532	        header: PacketHeader,
   533	        payload: Vec<u8>,
   534	        from_udp: bool,
   535	    ) -> Result<SessionEvent, SessionError> {
   536	        let mut inner = self.inner.lock().map_err(|_| SessionError::Poisoned)?;
   537	        if inner.state != SessionState::Ready {
   538	            return Err(SessionError::NotReady);
   539	        }
   540	        match header.packet_type {
   541	            PacketType::FrameHeader if from_udp => Ok(inner
   542	                .frames
   543	                .push_header(
   544	                    FrameHeader::decode(&payload)?,
   545	                    header.timestamp_ms,
   546	                    std::time::Instant::now(),
   547	                )?
   548	                .map_or(SessionEvent::Ignored, SessionEvent::Frame)),
   549	            PacketType::FrameChunk if from_udp => Ok(inner
   550	                .frames
   551	                .push_chunk(FrameChunk::decode(&payload)?, std::time::Instant::now())?
   552	                .map_or(SessionEvent::Ignored, SessionEvent::Frame)),
   553	            PacketType::AudioFrame if from_udp => Ok(inner
   554	                .audio
   555	                .push(AudioFragment::decode(&payload)?)
   556	                .map_or(SessionEvent::Ignored, SessionEvent::Audio)),
   557	            PacketType::CursorUpdate if from_udp => {
   558	                inner.cursor.update(CursorUpdate::decode(&payload)?);
   559	                Ok(SessionEvent::Cursor(inner.cursor))
   560	            }
   561	            PacketType::Ping => {
   562	                drop(inner);
   563	                self.send_control(ControlMessage::Pong)?;
   564	                Ok(SessionEvent::Ping)
   565	            }
   566	            PacketType::Control => match ControlMessage::decode(&payload)? {
   567	                ControlMessage::Ping => {
   568	                    drop(inner);
   569	                    self.send_control(ControlMessage::Pong)?;
   570	                    Ok(SessionEvent::Ping)
   571	                }
   572	                ControlMessage::ClipboardSyncUpdate(update) => {
   573	                    Ok(SessionEvent::Clipboard(update.text))
   574	                }
   575	                _ => Ok(SessionEvent::Ignored),
   576	            },
   577	            _ => Ok(SessionEvent::Ignored),
   578	        }
   579	    }
   580	}
