    40	/// Parses one access unit containing 4-byte big-endian length-prefixed HEVC NALUs.
    41	pub fn parse_length_prefixed_nalus(access_unit: &[u8]) -> Result<Vec<Nalu<'_>>, DecodeError> {
    42	    let mut offset = 0;
    43	    let mut nalus = Vec::new();
    44	    while offset < access_unit.len() {
    45	        if access_unit.len() - offset < NAL_LENGTH_BYTES {
    46	            return Err(DecodeError::TruncatedNalu { offset });
    47	        }
    48	        let length = u32::from_be_bytes(
    49	            access_unit[offset..offset + NAL_LENGTH_BYTES]
    50	                .try_into()
    51	                .expect("four-byte NAL length"),
    52	        ) as usize;
    53	        let length_offset = offset;
    54	        offset += NAL_LENGTH_BYTES;
    55	        if length == 0 {
    56	            return Err(DecodeError::EmptyNalu {
    57	                offset: length_offset,
    58	            });
    59	        }
    60	        let end = offset
    61	            .checked_add(length)
    62	            .filter(|end| *end <= access_unit.len())
    63	            .ok_or(DecodeError::TruncatedNalu {
    64	                offset: length_offset,
    65	            })?;
    66	        let data = &access_unit[offset..end];
    67	        nalus.push(Nalu {
    68	            nal_type: (data[0] >> 1) & 0x3f,
    69	            data,
    70	        });
    71	        offset = end;
    72	    }
    73	    Ok(nalus)
    74	}
