    76	/// Extracts the direct AVCC-style VPS/SPS/PPS blob expected by the decoder context.
    77	pub fn hevc_parameter_set_blob(access_unit: &[u8]) -> Result<Vec<u8>, DecodeError> {
    78	    let mut parameter_sets: [Option<&[u8]>; 3] = [None, None, None];
    79	    for nalu in parse_length_prefixed_nalus(access_unit)? {
    80	        match nalu.nal_type {
    81	            32 => parameter_sets[0] = Some(nalu.data),
    82	            33 => parameter_sets[1] = Some(nalu.data),
    83	            34 => parameter_sets[2] = Some(nalu.data),
    84	            _ => {}
    85	        }
    86	    }
    87	    if parameter_sets.iter().any(Option::is_none) {
    88	        return Err(DecodeError::MissingParameterSets);
    89	    }
    90	    let mut output = Vec::new();
    91	    for parameter_set in parameter_sets.into_iter().flatten() {
    92	        output.extend_from_slice(&(parameter_set.len() as u32).to_be_bytes());
    93	        output.extend_from_slice(parameter_set);
    94	    }
    95	    Ok(output)
    96	}
