   193	        pub fn flush(&mut self) -> Result<Vec<Nv12Frame>, DecodeError> {
   194	            self.decoder
   195	                .send_eof()
   196	                .map_err(|error| DecodeError::Ffmpeg(error.to_string()))?;
   197	            self.receive_available(0)
   198	        }
