   200	        fn receive_available(
   201	            &mut self,
   202	            fallback_timestamp_ms: i64,
   203	        ) -> Result<Vec<Nv12Frame>, DecodeError> {
   204	            let mut frames = Vec::new();
   205	            loop {
   206	                let mut decoded = frame::Video::empty();
   207	                match self.decoder.receive_frame(&mut decoded) {
   208	                    Ok(()) => {
   209	                        let timestamp_ms = decoded
   210	                            .timestamp()
   211	                            .or_else(|| decoded.pts())
   212	                            .unwrap_or(fallback_timestamp_ms);
   213	                        if matches!(
   214	                            decoded.format(),
   215	                            Pixel::VIDEOTOOLBOX | Pixel::D3D11 | Pixel::D3D11VA_VLD
   216	                        ) {
   217	                            let decoded = transfer_hardware_frame(&decoded)?;
   218	                            frames.push(self.to_nv12(&decoded, timestamp_ms)?);
   219	                        } else {
   220	                            frames.push(self.to_nv12(&decoded, timestamp_ms)?);
   221	                        }
   222	                    }
   223	                    Err(ffmpeg::Error::Other { errno }) if errno == ffmpeg::error::EAGAIN => break,
   224	                    Err(ffmpeg::Error::Eof) => break,
   225	                    Err(error) => return Err(DecodeError::Ffmpeg(error.to_string())),
   226	                }
   227	            }
   228	            Ok(frames)
   229	        }
   230	
   231	        fn to_nv12(
   232	            &mut self,
   233	            decoded: &frame::Video,
   234	            timestamp_ms: i64,
   235	        ) -> Result<Nv12Frame, DecodeError> {
   236	            let converted;
   237	            let source = if decoded.format() == Pixel::NV12 {
   238	                decoded
   239	            } else {
   240	                let needs_scaler = self.scaler.as_ref().is_none_or(|scaler| {
   241	                    scaler.input().format != decoded.format()
   242	                        || scaler.input().width != decoded.width()
   243	                        || scaler.input().height != decoded.height()
   244	                });
   245	                if needs_scaler {
   246	                    self.scaler = Some(
   247	                        scaling::Context::get(
   248	                            decoded.format(),
   249	                            decoded.width(),
   250	                            decoded.height(),
   251	                            Pixel::NV12,
   252	                            decoded.width(),
   253	                            decoded.height(),
   254	                            scaling::Flags::FAST_BILINEAR,
   255	                        )
   256	                        .map_err(|error| DecodeError::Ffmpeg(error.to_string()))?,
   257	                    );
   258	                }
   259	                converted = {
   260	                    let mut converted = frame::Video::empty();
   261	                    self.scaler
   262	                        .as_mut()
   263	                        .expect("scaler initialized above")
   264	                        .run(decoded, &mut converted)
   265	                        .map_err(|error| DecodeError::Ffmpeg(error.to_string()))?;
   266	                    converted
   267	                };
   268	                &converted
   269	            };
   270	            copy_nv12(source, timestamp_ms)
   271	        }
   272	    }
