   274	    impl Drop for HevcDecoder {
   275	        fn drop(&mut self) {
   276	            unsafe {
   277	                if !self.hw_device.is_null() {
   278	                    ffmpeg::ffi::av_buffer_unref(&mut self.hw_device);
   279	                }
   280	                // Prevent AVCodecContext from freeing the Vec-owned extradata.
   281	                let context = self.decoder.as_mut_ptr();
   282	                (*context).extradata = ptr::null_mut();
