   300	    fn copy_nv12(frame: &frame::Video, timestamp_ms: i64) -> Result<Nv12Frame, DecodeError> {
   301	        if frame.format() != Pixel::NV12 || frame.planes() < 2 {
   302	            return Err(DecodeError::UnsupportedFrame);
   303	        }
   304	        let width = frame.width() as usize;
   305	        let height = frame.height() as usize;
   306	        let y_stride = frame.stride(0);
   307	        let uv_stride = frame.stride(1);
   308	        let mut y_plane = vec![0_u8; width * height];
   309	        let mut uv_plane = vec![0_u8; width * ((height + 1) / 2)];
   310	        for row in 0..height {
   311	            let source = &frame.data(0)[row * y_stride..row * y_stride + width];
   312	            y_plane[row * width..(row + 1) * width].copy_from_slice(source);
   313	        }
   314	        for row in 0..((height + 1) / 2) {
   315	            let source = &frame.data(1)[row * uv_stride..row * uv_stride + width];
   316	            uv_plane[row * width..(row + 1) * width].copy_from_slice(source);
   317	        }
   318	        Ok(Nv12Frame {
   319	            width: width as u32,
   320	            height: height as u32,
   321	            y_stride: width,
   322	            uv_stride: width,
   323	            y_plane,
   324	            uv_plane,
   325	            timestamp_ms,
   326	        })
   327	    }
