   155	    unsafe fn copy_video_frame(sample: &CMSampleBuffer) -> Option<CaptureFrame> {
   156	        let image = sample.image_buffer()?;
   157	        if CVPixelBufferGetPixelFormatType(&image) != kCVPixelFormatType_32BGRA {
   158	            return None;
   159	        }
   160	        let flags = CVPixelBufferLockFlags::ReadOnly;
   161	        if CVPixelBufferLockBaseAddress(&image, flags) != 0 {
   162	            return None;
   163	        }
   164	        let width = CVPixelBufferGetWidth(&image);
   165	        let height = CVPixelBufferGetHeight(&image);
   166	        let bytes_per_row = CVPixelBufferGetBytesPerRow(&image);
   167	        let base = CVPixelBufferGetBaseAddress(&image).cast::<u8>();
   168	        let bgra = if base.is_null() {
   169	            None
   170	        } else {
   171	            Some(std::slice::from_raw_parts(base, bytes_per_row * height).to_vec())
   172	        };
   173	        let _ = CVPixelBufferUnlockBaseAddress(&image, flags);
   174	        bgra.map(|bgra| CaptureFrame {
   175	            width: width as u32,
   176	            height: height as u32,
   177	            bytes_per_row,
   178	            bgra,
   179	            captured_at: Instant::now(),
   180	        })
   181	    }
   182	
   183	    unsafe fn copy_audio_frame(sample: &CMSampleBuffer) -> Option<Vec<u8>> {
   184	        let block = sample.data_buffer()?;
   185	        let length = block.data_length();
   186	        if length == 0 {
   187	            return None;
   188	        }
   189	        let mut bytes = vec![0_u8; length];
   190	        let destination = NonNull::new(bytes.as_mut_ptr().cast()).expect("Vec pointer is non-null");
   191	        if block.copy_data_bytes(0, length, destination) != 0 {
   192	            return None;
   193	        }
   194	        Some(bytes)
   195	    }
