   227	        pub fn start(
   228	            config: CaptureConfig,
   229	        ) -> Result<(Self, mpsc::Receiver<CaptureEvent>), CaptureError> {
   230	            if unsafe { !CGPreflightScreenCaptureAccess() && !CGRequestScreenCaptureAccess() } {
   231	                return Err(CaptureError::PermissionDenied);
   232	            }
   233	
   234	            objc2::rc::autoreleasepool(|_| unsafe {
   235	                let (content_tx, content_rx) = mpsc::channel::<*mut SCShareableContent>();
   236	                let completion = RcBlock::new(
   237	                    move |content: *mut SCShareableContent, error: *mut NSError| {
   238	                        if error.is_null() && !content.is_null() {
   239	                            // Required ownership rule from the proven spike: the completion
   240	                            // returns an autoreleased object, so retain before crossing the
   241	                            // callback boundary and transfer our +1 through the raw pointer.
   242	                            let retained = Retained::retain(content).expect("non-null SCK content");
   243	                            let _ = content_tx
   244	                                .send(Retained::into_raw(retained) as *mut SCShareableContent);
   245	                        }
   246	                    },
   247	                );
   248	                SCShareableContent::getShareableContentWithCompletionHandler(&completion);
   249	                let raw_content = content_rx
   250	                    .recv_timeout(Duration::from_secs(10))
   251	                    .map_err(|_| CaptureError::Timeout)?;
   252	                let content = Retained::from_raw(raw_content).ok_or_else(|| {
   253	                    CaptureError::ScreenCaptureKit("null shareable content".into())
   254	                })?;
   255	                let displays = content.displays();
   256	                if displays.count() == 0 {
   257	                    return Err(CaptureError::NoDisplay);
   258	                }
   259	                let main_id = CGDisplay::main().id;
   260	                let display = (0..displays.count())
   261	                    .map(|index| displays.objectAtIndex(index))
   262	                    .find(|display| display.displayID() == main_id)
   263	                    .unwrap_or_else(|| displays.objectAtIndex(0));
   264	
   265	                let filter = SCContentFilter::initWithDisplay_excludingWindows(
   266	                    SCContentFilter::alloc(),
   267	                    &display,
   268	                    &NSArray::new(),
   269	                );
   270	                let stream_config = SCStreamConfiguration::new();
   271	                stream_config.setWidth(config.width as usize);
   272	                stream_config.setHeight(config.height as usize);
   273	                stream_config.setQueueDepth(3);
   274	                stream_config.setShowsCursor(true);
   275	                stream_config.setPixelFormat(kCVPixelFormatType_32BGRA);
   276	                if config.frames_per_second > 0 {
   277	                    stream_config.setMinimumFrameInterval(objc2_core_media::CMTime::new(
   278	                        1,
   279	                        config.frames_per_second as i32,
   280	                    ));
   281	                } else {
   282	                    stream_config.setMinimumFrameInterval(objc2_core_media::kCMTimeZero);
   283	                }
   284	                stream_config.setCapturesAudio(config.capture_audio);
   285	                stream_config.setSampleRate(48_000);
   286	                stream_config.setChannelCount(2);
   287	
   288	                let stream = SCStream::initWithFilter_configuration_delegate(
   289	                    SCStream::alloc(),
   290	                    &filter,
   291	                    &stream_config,
   292	                    None,
   293	                );
   294	                let (sender, receiver) = mpsc::channel();
   295	                let sink = FrameSink::new(sender);
   296	                let queue = dispatch2::DispatchQueue::new("erd-host.sck-output", None);
   297	                stream
   298	                    .addStreamOutput_type_sampleHandlerQueue_error(
   299	                        ProtocolObject::from_ref(&*sink),
   300	                        SCStreamOutputType::Screen,
   301	                        Some(&queue),
   302	                    )
   303	                    .map_err(|error| CaptureError::ScreenCaptureKit(error.to_string()))?;
   304	                if config.capture_audio {
   305	                    stream
   306	                        .addStreamOutput_type_sampleHandlerQueue_error(
   307	                            ProtocolObject::from_ref(&*sink),
   308	                            SCStreamOutputType::Audio,
   309	                            Some(&queue),
   310	                        )
   311	                        .map_err(|error| CaptureError::ScreenCaptureKit(error.to_string()))?;
   312	                }
   313	
   314	                let (started_tx, started_rx) = mpsc::sync_channel(1);
   315	                let started = RcBlock::new(move |error: *mut NSError| {
   316	                    let result = if error.is_null() {
   317	                        Ok(())
   318	                    } else {
   319	                        Err((*error).localizedDescription().to_string())
   320	                    };
   321	                    let _ = started_tx.send(result);
   322	                });
   323	                stream.startCaptureWithCompletionHandler(Some(&started));
   324	                started_rx
   325	                    .recv_timeout(Duration::from_secs(10))
   326	                    .map_err(|_| CaptureError::Timeout)?
   327	                    .map_err(CaptureError::ScreenCaptureKit)?;
   328	
   329	                Ok((
   330	                    Self {
   331	                        display_info: Self::display_info()?,
   332	                        stream,
   333	                        _sink: sink,
   334	                        _queue: queue,
   335	                    },
   336	                    receiver,
   337	                ))
   338	            })
   339	        }
