    27	#[derive(Debug, Error, PartialEq, Eq)]
    28	pub enum MediaAssemblyError {
    29	    #[error("frame header exceeds protocol caps")]
    30	    InvalidHeader,
    31	    #[error("frame chunk index is outside the declared frame")]
    32	    InvalidChunkIndex,
    33	    #[error("assembled frame size differs from its header")]
