    46	impl FrameAssembler {
    47	    pub fn push_header(
    48	        &mut self,
    49	        header: FrameHeader,
    50	        timestamp_ms: u32,
    51	        now: Instant,
    52	    ) -> Result<Option<AssembledFrame>, MediaAssemblyError> {
    53	        if header.total_chunks == 0
    54	            || header.total_chunks > MAX_CHUNKS_PER_FRAME
    55	            || header.total_size == 0
    56	            || header.total_size > MAX_FRAME_BYTES
    57	        {
    58	            return Err(MediaAssemblyError::InvalidHeader);
    59	        }
    60	        self.expire(now);
    61	        self.track_loss(header.frame_id, now);
    62	        if header.is_key_frame {
    63	            self.frames.retain(|frame_id, assembly| {
    64	                *frame_id >= header.frame_id || Self::complete(assembly)
    65	            });
    66	        }
    67	        let chunks = self.orphans.remove(&header.frame_id).unwrap_or_default();
    68	        let frame_id = header.frame_id;
    69	        let assembly = FrameAssembly {
    70	            header,
    71	            chunks,
    72	            started: now,
    73	            timestamp_ms,
    74	        };
    75	        self.frames.insert(frame_id, assembly);
    76	        self.finish_if_complete(frame_id)
    77	    }
    78	
    79	    pub fn push_chunk(
    80	        &mut self,
    81	        chunk: FrameChunk,
    82	        now: Instant,
    83	    ) -> Result<Option<AssembledFrame>, MediaAssemblyError> {
    84	        self.expire(now);
    85	        if let Some(assembly) = self.frames.get_mut(&chunk.frame_id) {
    86	            if chunk.chunk_index >= assembly.header.total_chunks {
    87	                return Err(MediaAssemblyError::InvalidChunkIndex);
    88	            }
    89	            assembly
    90	                .chunks
    91	                .entry(chunk.chunk_index)
    92	                .or_insert(chunk.data);
    93	            return self.finish_if_complete(chunk.frame_id);
    94	        }
    95	
    96	        if self.orphans.len() >= MAX_ORPHAN_FRAMES && !self.orphans.contains_key(&chunk.frame_id) {
    97	            return Ok(None);
    98	        }
    99	        let orphans = self.orphans.entry(chunk.frame_id).or_default();
   100	        if orphans.len() >= MAX_CHUNKS_PER_FRAME as usize {
   101	            self.orphans.remove(&chunk.frame_id);
   102	            return Ok(None);
   103	        }
   104	        orphans.entry(chunk.chunk_index).or_insert(chunk.data);
   105	        Ok(None)
   106	    }
   107	
   108	    pub fn loss_ratio(&mut self, now: Instant) -> f64 {
   109	        self.trim_loss(now);
   110	        let (lost, total) = self.recent_loss.iter().fold(
   111	            (0_u64, 0_u64),
   112	            |(lost, total), (_, entry_lost, entry_total)| (lost + entry_lost, total + entry_total),
   113	        );
   114	        if total == 0 {
   115	            0.0
   116	        } else {
   117	            lost as f64 / total as f64
   118	        }
   119	    }
   120	
   121	    pub fn completed_frames(&self) -> u64 {
   122	        self.completed_frames
   123	    }
   124	
   125	    pub fn clear(&mut self) {
   126	        self.frames.clear();
   127	        self.orphans.clear();
   128	        self.expected_frame_id = None;
   129	        self.recent_loss.clear();
   130	        self.completed_frames = 0;
   131	    }
   132	
   133	    fn finish_if_complete(
   134	        &mut self,
   135	        frame_id: u32,
   136	    ) -> Result<Option<AssembledFrame>, MediaAssemblyError> {
   137	        let Some(assembly) = self.frames.get(&frame_id) else {
   138	            return Ok(None);
   139	        };
   140	        if !Self::complete(assembly) {
   141	            return Ok(None);
   142	        }
   143	        let assembly = self.frames.remove(&frame_id).expect("frame existed above");
   144	        let mut data = Vec::with_capacity(assembly.header.total_size as usize);
   145	        for index in 0..assembly.header.total_chunks {
   146	            data.extend_from_slice(
   147	                assembly
   148	                    .chunks
   149	                    .get(&index)
   150	                    .ok_or(MediaAssemblyError::SizeMismatch)?,
   151	            );
   152	        }
   153	        if data.len() != assembly.header.total_size as usize {
   154	            return Err(MediaAssemblyError::SizeMismatch);
   155	        }
   156	        self.completed_frames += 1;
   157	        Ok(Some(AssembledFrame {
   158	            header: assembly.header,
   159	            data,
   160	            timestamp_ms: assembly.timestamp_ms,
   161	        }))
   162	    }
   163	
   164	    fn complete(assembly: &FrameAssembly) -> bool {
   165	        assembly.chunks.len() == assembly.header.total_chunks as usize
   166	    }
   167	
   168	    fn expire(&mut self, now: Instant) {
   169	        self.frames.retain(|_, assembly| {
   170	            now.saturating_duration_since(assembly.started) < ASSEMBLY_TIMEOUT
   171	        });
   172	    }
   173	
   174	    fn track_loss(&mut self, frame_id: u32, now: Instant) {
   175	        let lost = self
   176	            .expected_frame_id
   177	            .map_or(0, |expected| frame_id.saturating_sub(expected) as u64);
   178	        self.recent_loss.push_back((now, lost, lost + 1));
   179	        self.expected_frame_id = Some(
   180	            self.expected_frame_id
   181	                .map_or(frame_id.wrapping_add(1), |expected| {
   182	                    expected.max(frame_id.wrapping_add(1))
   183	                }),
   184	        );
   185	        self.trim_loss(now);
   186	    }
   187	
   188	    fn trim_loss(&mut self, now: Instant) {
   189	        while self.recent_loss.front().is_some_and(|(timestamp, _, _)| {
   190	            now.saturating_duration_since(*timestamp) > Duration::from_secs(5)
   191	        }) {
   192	            self.recent_loss.pop_front();
   193	        }
   194	    }
   195	}
