     5	/// Fixed-capacity lock-free or single-threaded ring buffer for low-latency per-frame measurement.
     6	#[derive(Debug, Clone)]
     7	pub struct LatencyRecorder {
     8	    samples: Vec<u64>,
     9	    capacity: usize,
    10	    index: usize,
    11	    count: u64,
    12	}
    13	
    14	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    15	pub struct LatencyStats {
    16	    pub frames: u64,
    17	    pub p50_us: u64,
    18	    pub p95_us: u64,
    19	    pub p99_us: u64,
    20	    pub max_us: u64,
    21	}
    22	
    23	impl Default for LatencyRecorder {
    24	    fn default() -> Self {
    25	        Self::new()
    26	    }
    27	}
    28	
    29	impl LatencyRecorder {
    30	    pub const DEFAULT_CAPACITY: usize = 4096;
    31	
    32	    pub fn new() -> Self {
    33	        Self::with_capacity(Self::DEFAULT_CAPACITY)
    34	    }
    35	
    36	    pub fn with_capacity(capacity: usize) -> Self {
    37	        let capacity = capacity.max(1);
    38	        Self {
    39	            samples: Vec::with_capacity(capacity),
    40	            capacity,
    41	            index: 0,
    42	            count: 0,
    43	        }
    44	    }
    45	
    46	    /// Records a per-frame sample from capture timestamp (if present, else receive Instant),
    47	    /// decode timestamp, and present timestamp.
    48	    pub fn record_sample(
    49	        &mut self,
    50	        capture_ts: Option<Instant>,
    51	        decode_ts: Instant,
    52	        present_ts: Instant,
    53	    ) {
    54	        let start = capture_ts.unwrap_or(decode_ts);
    55	        let latency = present_ts.saturating_duration_since(start);
    56	        self.record_duration(latency);
    57	    }
    58	
    59	    /// Ingests a frame latency as a `Duration`.
    60	    pub fn record_duration(&mut self, latency: Duration) {
    61	        let us = latency.as_micros().min(u64::MAX as u128) as u64;
    62	        self.record_us(us);
    63	    }
    64	
    65	    /// Ingests a latency sample directly in microseconds.
    66	    pub fn record_us(&mut self, latency_us: u64) {
    67	        if self.samples.len() < self.capacity {
    68	            self.samples.push(latency_us);
    69	        } else {
    70	            self.samples[self.index] = latency_us;
    71	        }
    72	        self.index = (self.index + 1) % self.capacity;
    73	        self.count = self.count.saturating_add(1);
    74	    }
    75	
    76	    pub fn frame_count(&self) -> u64 {
    77	        self.count
    78	    }
    79	
    80	    pub fn is_empty(&self) -> bool {
    81	        self.count == 0
    82	    }
    83	
    84	    pub fn stats(&self) -> LatencyStats {
    85	        if self.samples.is_empty() {
    86	            return LatencyStats {
    87	                frames: 0,
    88	                p50_us: 0,
    89	                p95_us: 0,
    90	                p99_us: 0,
    91	                max_us: 0,
    92	            };
    93	        }
    94	
    95	        let mut sorted = self.samples.clone();
    96	        sorted.sort_unstable();
    97	
    98	        let len = sorted.len();
    99	        let p50_us = percentile_sorted(&sorted, 0.50);
   100	        let p95_us = percentile_sorted(&sorted, 0.95);
   101	        let p99_us = percentile_sorted(&sorted, 0.99);
   102	        let max_us = sorted[len - 1];
   103	
   104	        LatencyStats {
   105	            frames: self.count,
   106	            p50_us,
   107	            p95_us,
   108	            p99_us,
   109	            max_us,
   110	        }
   111	    }
   112	
   113	    pub fn stats_json(&self) -> String {
   114	        serde_json::to_string(&self.stats()).unwrap_or_else(|_| {
   115	            r#"{"frames":0,"p50_us":0,"p95_us":0,"p99_us":0,"max_us":0}"#.to_string()
   116	        })
   117	    }
   118	}
   119	
   120	fn percentile_sorted(sorted: &[u64], percentile: f64) -> u64 {
   121	    let len = sorted.len();
   122	    if len == 0 {
   123	        return 0;
   124	    }
   125	    if len == 1 {
   126	        return sorted[0];
   127	    }
   128	    let rank = ((len - 1) as f64 * percentile.clamp(0.0, 1.0)).round() as usize;
   129	    sorted[rank.min(len - 1)]
   130	}
