    77	fn parse_hex_32(hex_str: &str) -> Result<Vec<u8>> {
    78	    let trimmed = hex_str.trim();
    79	    if trimmed.len() != 64 {
    80	        bail!("psk-hex must be exactly 64 hex characters (32 bytes), got length {}", trimmed.len());
    81	    }
    82	    let mut bytes = Vec::with_capacity(32);
    83	    for i in (0..64).step_by(2) {
    84	        let byte = u8::from_str_radix(&trimmed[i..i + 2], 16)
    85	            .with_context(|| format!("invalid hex digit pair '{}'", &trimmed[i..i + 2]))?;
    86	        bytes.push(byte);
    87	    }
    88	    Ok(bytes)
    89	}
