    fn annex_b_is_converted_to_avcc_and_parameter_sets_prepend_keyframes() {
        let vps = nalu(32, 1);
        let sps = nalu(33, 2);
        let pps = nalu(34, 3);
        let idr = nalu(19, 4);
        let mut annex_b = Vec::new();
        for unit in [&vps, &sps, &pps, &idr] {
